"""Text-to-SQL harness: draft -> execute -> diagnose -> one repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task (env.max_calls)
  env.schema(db_id) -> str                       CREATE statements
  env.execute(sql, max_rows=20) -> dict          read-only run {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if shipped, else ""
  env.prompt(name) -> str                        text of another harness file
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
CREATE_RE = re.compile(
    r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([A-Za-z_][\w$]*)[\"'`\]]?\s*\((.*?)\)\s*;",
    re.S | re.I,
)
COL_RE = re.compile(r"^\s*[\"'`\[]?([A-Za-z_][\w$]*)[\"'`\]]?\s+([A-Za-z]+)")
CONSTRAINT_KW = {
    "primary", "foreign", "unique", "check", "constraint", "key", "index", "exclude",
}
LITERAL_RE = re.compile(r"(?:([A-Za-z_][\w$]*)\s*\.\s*)?([A-Za-z_][\w$]*)\s*(=|LIKE|IS)\s*'([^']*)'", re.I)
IN_LIST_RE = re.compile(r"([A-Za-z_][\w$]*)\s+IN\s*\(\s*('[^)]*?)\)", re.I)
QUOTED_RE = re.compile(r"'([^']*)'")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _tables(schema):
    """{table_name: [column names]} parsed from CREATE statements."""
    out = {}
    for name, body in CREATE_RE.findall(schema or ""):
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            m = COL_RE.match(p)
            if m and m.group(1).lower() not in CONSTRAINT_KW:
                cols.append(m.group(1))
        out[name] = cols
    return out


def _resolve(tables, col, qual=None):
    """Find the real table owning a column referenced in the draft SQL."""
    cl = col.lower()
    if qual:
        for t, cols in tables.items():
            if t.lower() == qual.lower() and any(c.lower() == cl for c in cols):
                return t, next(c for c in cols if c.lower() == cl)
    hits = [(t, c) for t, cols in tables.items() for c in cols if c.lower() == cl]
    if len(hits) == 1:
        return hits[0]
    return None


def _literals(sql):
    """[(qualifier, column, operator, value)] for string comparisons in the SQL."""
    found = []
    for qual, col, op, val in LITERAL_RE.findall(sql or ""):
        found.append((qual or None, col, op.upper(), val))
    for col, blob in IN_LIST_RE.findall(sql or ""):
        for val in QUOTED_RE.findall(blob):
            found.append((None, col, "=", val))
    return found


def _run(env, sql, max_rows=5):
    try:
        r = env.execute(sql, max_rows=max_rows)
    except Exception as exc:  # never let diagnostics kill the task
        return {"ok": False, "error": str(exc), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(r, dict):
        return {"ok": False, "error": "no result", "rows": [], "columns": [], "n_rows": 0}
    return r


def _fmt_rows(res, limit=5):
    if not res.get("ok"):
        return "ERROR: %s" % str(res.get("error"))[:200]
    rows = res.get("rows") or []
    if not rows:
        return "(no rows)"
    return "; ".join(repr(tuple(r)) for r in rows[:limit])


def build_diagnostics(task, env, sql, schema, result):
    """Cheap, generic probes explaining why a draft returned nothing / failed."""
    lines = []
    tables = _tables(schema)
    seen = set()
    budget = 10
    for qual, col, op, val in _literals(sql):
        if budget <= 0:
            break
        key = (col.lower(), val)
        if key in seen:
            continue
        seen.add(key)
        resolved = _resolve(tables, col, qual)
        if not resolved:
            continue
        t, c = resolved
        budget -= 1
        if op == "LIKE":
            core = val.replace("%", "").replace("_", " ").strip()
            frag = core.split()[0] if core.split() else core
            if frag:
                probe = (
                    'SELECT "%s", COUNT(*) FROM "%s" WHERE "%s" LIKE \'%%%s%%\' GROUP BY "%s" LIMIT 5'
                    % (c, t, c, frag, c)
                )
                r = _run(env, probe)
                lines.append(
                    "Rows whose %s.%s contains %r (value, count): %s" % (t, c, frag, _fmt_rows(r))
                )
        else:
            probe = 'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" IS NOT NULL LIMIT 8' % (c, t, c)
            r = _run(env, probe)
            lines.append("Sample values of %s.%s: %s" % (t, c, _fmt_rows(r, 8)))
            frag = val.strip().split()[0] if val.strip() else ""
            if frag and frag.lower() != val.strip().lower():
                probe = (
                    'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" LIKE \'%%%s%%\' LIMIT 8'
                    % (c, t, c, frag)
                )
                r = _run(env, probe)
                lines.append("Values of %s.%s containing %r: %s" % (t, c, frag, _fmt_rows(r, 8)))
    if not lines and tables:
        # No usable literal probes: show table sizes so empty joins can be located.
        for t in list(tables)[:4]:
            r = _run(env, 'SELECT COUNT(*) FROM "%s"' % t)
            lines.append("Row count of %s: %s" % (t, _fmt_rows(r, 1)))
    return "\n".join(lines[:10])


REPAIR_RULES = (
    "Your previous query did not answer the question. Write a corrected SQLite query.\n"
    "- If it returned 0 rows but the question implies answers exist, your filter or join is wrong: "
    "use the ACTUAL stored values shown below (exact spelling/case/punctuation), relax over-strict "
    "predicates, use LIKE '%...%' for text containment, and check join keys against the schema.\n"
    "- For 'X that has no Y' / 'not in' questions, exclude ids appearing on EITHER side of the "
    "relation table (e.g. NOT IN (SELECT a FROM rel) AND NOT IN (SELECT b FROM rel)), or use NOT EXISTS.\n"
    "- Match the requested output columns exactly: entity 'details'/'all information' -> that table's "
    "columns (T.*); a named attribute -> only that attribute; do not add extra columns or DISTINCT "
    "unless asked.\n"
    "- If the query errored, fix the syntax/column names using the schema.\n"
    "Return ONLY the corrected query in one ```sql block."
)


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s" % (task["db_id"], schema)
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    user += "\n\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    result = _run(env, sql, max_rows=5)
    ok = bool(result.get("ok"))
    nrows = result.get("n_rows") or 0
    needs_repair = (not ok) or nrows == 0
    if not needs_repair:
        return {"sql": sql}

    diag = build_diagnostics(task, env, sql, schema, result)
    if ok:
        status = "Execution result: 0 rows returned (the question expects matching data)."
    else:
        status = "Execution ERROR: %s" % str(result.get("error"))[:300]
    feedback = (
        REPAIR_RULES
        + "\n\nPrevious query:\n"
        + sql
        + "\n\n"
        + status
        + ("\n\nDiagnostics from the database:\n" + diag if diag else "")
        + "\n\nOriginal question: "
        + task["question"]
        + ("\nHint: " + task["hint"] if task.get("hint") else "")
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": feedback},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    result2 = _run(env, sql2, max_rows=5)
    if result2.get("ok") and (result2.get("n_rows") or 0) > 0:
        return {"sql": sql2}
    if result2.get("ok") and not ok:
        return {"sql": sql2}
    return {"sql": sql2 if result2.get("ok") else sql}

